/**
 * Cloudflare Worker — Gerar Carta de Autorização Split de Pagamento
 *
 * O modelo .docx fica embutido como base64 neste arquivo.
 * Para atualizar o modelo: substitua DOCX_BASE64 pelo novo base64.
 *
 * Variáveis de ambiente (Settings → Variables → Encrypt):
 *   PIPEFY_TOKEN   — token Bearer do Pipefy
 *   WORKER_SECRET  — chave secreta para proteger o endpoint
 *
 * Endpoint:
 *   POST /gerar-carta
 *   Header: X-Worker-Secret: <WORKER_SECRET>
 *   Body JSON: { "card_id": "1234567890" }
 */

import { PDFDocument, rgb, StandardFonts } from 'https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/+esm';

const PIPEFY_API = "https://api.pipefy.com/graphql";
const FIELD_ID   = "anexo_carta_de_aturoiza_o";
const ORG_ID     = 300738585;

// Modelo .docx embutido — gerado a partir de:
// src/CARTA_DE_AUTORIZAÇÃO_-_AUTOMAÇÃO.docx
// Para atualizar: base64 -w0 src/CARTA_DE_AUTORIZAÇÃO_-_AUTOMAÇÃO.docx
const DOCX_BASE64 = "";

// Dimensões A4 em pontos (1pt = 1/72 inch)
const PAGE_W = 595.28;
const PAGE_H = 841.89;
const ML = 85;             // margem esquerda (3cm)
const MR = 85;             // margem direita (3cm)
const MT = 71;             // margem topo (2.5cm)
const CONTENT_W = PAGE_W - ML - MR;

// ─── Handler principal ─────────────────────────────────────────────────────
export default {
  async fetch(request, env, ctx) {
    console.info({ message: "Carta Split Worker recebeu uma requisicao" });

    if (request.method === "OPTIONS") return cors();

    const url = new URL(request.url);
    if (url.pathname !== "/gerar-carta") return json({ error: "Not found" }, 404);
    if (request.method !== "POST") return json({ error: "Method not allowed" }, 405);

    const secret = request.headers.get("X-Worker-Secret");
    if (!env.WORKER_SECRET || secret !== env.WORKER_SECRET) return json({ error: "Unauthorized" }, 401);

    let body;
    try { body = await request.json(); }
    catch { return json({ error: "Body JSON invalido" }, 400); }

    const cardId = body.card_id;
    if (!cardId) return json({ error: "card_id e obrigatorio" }, 400);

    try {
      console.info({ message: `Processando card ${cardId}` });

      const dados = await buscarDadosCard(cardId, env.PIPEFY_TOKEN);
      console.info({ message: "Dados obtidos", cliente: dados.nomeCliente });

      const pdfBytes = await gerarPdf(dados);
      console.info({ message: "PDF gerado" });

      await anexarPdfNoPipefy(cardId, dados.cpf, pdfBytes, env.PIPEFY_TOKEN);
      console.info({ message: `PDF anexado no card ${cardId}` });

      return json({ ok: true, card_id: cardId, msg: "Carta gerada e anexada com sucesso." });

    } catch (err) {
      console.error("Erro:", err.message);
      return json({ ok: false, error: err.message }, 500);
    }
  }
};

// ─── 1. Busca campos do card no Pipefy ────────────────────────────────────
async function buscarDadosCard(cardId, token) {
  const query = `
    query {
      card(id: "${cardId}") {
        fields { name value }
      }
    }
  `;
  const res = await pipefyFetch(query, token);
  const card = res.data?.card;
  if (!card) throw new Error(`Card ${cardId} nao encontrado`);

  const campos = {};
  for (const f of card.fields || []) {
    if (f.value) campos[f.name] = f.value;
  }

  const dadosBoletoRaw = campos["Dados Boleto"] || "";
  const dadosBoleto    = parseBoletos(dadosBoletoRaw);
  const dataCarta      = formatarDataPortugues(campos["Data Emissão da Carta"] || "");
  const dataContrato   = formatarDataDDMMYYYY(campos["Data emissão do contrato CCB"] || "");

  return {
    dataCarta,
    valorTotal:  campos["Valor total dos boletos"] || "",
    idContrato:  campos["ID do contrato CCB"]      || "",
    dataContrato,
    dadosBoleto,
    nomeCliente: campos["Nome do Cliente"]         || "",
    cpf:         campos["CPF do Cliente"]          || "",
  };
}

// ─── Parse dos boletos ─────────────────────────────────────────────────────
function parseBoletos(texto) {
  if (!texto) return [];
  const vistos = new Set();
  return texto.split(/\n\s*\n/)
    .map(b => b.trim()).filter(Boolean)
    .filter(b => { if (vistos.has(b)) return false; vistos.add(b); return true; })
    .map(bloco => ({
      razao:    extrair(bloco, /Raz.o Social\/Nome do Favorecido:\s*(.*)/i),
      cnpj:     extrair(bloco, /CNPJ\/CPF:\s*(.*)/i),
      boleto:   extrair(bloco, /Boleto:\s*(.*)/i),
      contrato: extrair(bloco, /Contrato:\s*(.*)/i),
      valor:    extrair(bloco, /Valor:\s*(.*)/i),
    }))
    .filter(b => b.razao);
}

function extrair(texto, regex) {
  return texto.match(regex)?.[1]?.trim() || "";
}

// ─── 2. Gera PDF com pdf-lib ───────────────────────────────────────────────
async function gerarPdf(d) {
  const pdfDoc = await PDFDocument.create();
  const page   = pdfDoc.addPage([PAGE_W, PAGE_H]);

  const fontR = await pdfDoc.embedFont(StandardFonts.TimesRoman);
  const fontB = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
  const FS    = 12;
  const LS    = FS * 1.5;
  const black = rgb(0, 0, 0);

  let y = PAGE_H - MT;

  // Desenha linha simples
  function line(text, bold = false, spaceBefore = 0) {
    y -= spaceBefore;
    if (!text) { y -= LS; return; }
    page.drawText(san(text), {
      x: ML, y,
      size: FS,
      font: bold ? fontB : fontR,
      color: black,
    });
    y -= LS;
  }

  // Desenha texto centralizado
  function center(text, bold = false, spaceBefore = 0) {
    y -= spaceBefore;
    const font = bold ? fontB : fontR;
    const tw = font.widthOfTextAtSize(san(text), FS);
    page.drawText(san(text), {
      x: (PAGE_W - tw) / 2, y,
      size: FS, font, color: black,
    });
    y -= LS;
  }

  // Desenha parágrafo com quebra de linha automática
  function paragraph(text, bold = false, spaceBefore = 0) {
    y -= spaceBefore;
    const font = bold ? fontB : fontR;
    for (const l of wrapText(san(text), font, FS, CONTENT_W)) {
      page.drawText(l, { x: ML, y, size: FS, font, color: black });
      y -= LS;
    }
  }

  // Desenha linha com prefixo em negrito + valor normal
  function mixed(prefix, value, spaceBefore = 0) {
    y -= spaceBefore;
    const pw = fontB.widthOfTextAtSize(san(prefix), FS);
    page.drawText(san(prefix), { x: ML,      y, size: FS, font: fontB, color: black });
    page.drawText(san(value),  { x: ML + pw, y, size: FS, font: fontR, color: black });
    y -= LS;
  }

  // ── Conteúdo da carta (fiel ao modelo Word) ────────────────────────────
  mixed("São Paulo, SP, ", `${d.dataCarta}.`);
  line("");
  line("À");
  line("BMP SOCIEDADE DE CRÉDITO DIRETO S.A.", true);
  line("", false, LS);
  center("AUTORIZAÇÃO", true);
  line("");

  paragraph(
    `Autorizamos a transferência do montante de ${d.valorTotal}, oriundo do Valor Líquido de Crédito da CCB nº ${d.idContrato}, emitida em ${d.dataContrato} para os seguintes destinatários:`
  );
  line("");

  for (const b of d.dadosBoleto) {
    line(b.razao, true);
    if (b.cnpj)     mixed("CNPJ/CPF: ",  b.cnpj);
    if (b.boleto)   mixed("Boleto: ",    b.boleto);
    if (b.contrato) mixed("Contrato: ",  b.contrato);
    if (b.valor)    mixed("Valor: ",     b.valor);
    line("");
  }

  // Linha de assinatura
  y -= LS * 2;
  page.drawLine({
    start: { x: ML, y: y + LS * 0.3 },
    end:   { x: ML + 280, y: y + LS * 0.3 },
    thickness: 0.5,
    color: black,
  });
  y -= LS * 0.5;

  mixed("EMITENTE: ",    d.nomeCliente);
  mixed("CNPJ / CPF: ", d.cpf);

  return await pdfDoc.save();
}

// Quebra texto em linhas que cabem na largura
function wrapText(text, font, size, maxW) {
  const words = text.split(" ");
  const lines = [];
  let cur = "";
  for (const w of words) {
    const candidate = cur ? `${cur} ${w}` : w;
    if (font.widthOfTextAtSize(candidate, size) <= maxW) {
      cur = candidate;
    } else {
      if (cur) lines.push(cur);
      cur = w;
    }
  }
  if (cur) lines.push(cur);
  return lines;
}

// Remove acentos e caracteres não suportados pelas fontes padrão PDF
function san(str) {
  return String(str || "")
    .replace(/[ãâáàä]/g, "a").replace(/[ÃÂÁÀ]/g, "A")
    .replace(/[êéèë]/g,  "e").replace(/[ÊÉÈ]/g,  "E")
    .replace(/[îíìï]/g,  "i").replace(/[ÎÍÌ]/g,  "I")
    .replace(/[ôóòõö]/g, "o").replace(/[ÔÓÒÕ]/g, "O")
    .replace(/[ûúùü]/g,  "u").replace(/[ÛÚÙ]/g,  "U")
    .replace(/[ç]/g, "c").replace(/[Ç]/g, "C")
    .replace(/[ñ]/g, "n").replace(/[Ñ]/g, "N")
    .replace(/[º]/g, "o").replace(/[ª]/g, "a")
    .replace(/[–—]/g, "-")
    .replace(/[""]/g, '"').replace(/['']/g, "'")
    .replace(/[^\x20-\x7E]/g, "");
}

// ─── 3. Upload e anexo no Pipefy ──────────────────────────────────────────
async function anexarPdfNoPipefy(cardId, cpf, pdfBytes, token) {
  const fileName = `CARTA_${cpf.replace(/[^\d]/g, "")}.pdf`;

  const mutPresigned = `
    mutation {
      createPresignedUrl(input: {
        organizationId: ${ORG_ID},
        fileName: "${fileName}"
      }) { url }
    }
  `;
  const presignedRes = await pipefyFetch(mutPresigned, token);
  const presignedUrl = presignedRes.data?.createPresignedUrl?.url;
  if (!presignedUrl) throw new Error("Falha ao obter presigned URL");

  const uploadRes = await fetch(presignedUrl, {
    method: "PUT",
    body: pdfBytes,
    headers: { "Content-Type": "application/pdf" },
  });
  if (!uploadRes.ok) throw new Error(`Falha no upload: ${uploadRes.status}`);

  const filePath = new URL(presignedUrl).pathname.replace(/^\//, "");

  const mutAnexo = `
    mutation {
      updateCardField(input: {
        card_id: ${cardId},
        field_id: "${FIELD_ID}",
        new_value: ["${filePath}"]
      }) { success }
    }
  `;
  const anexoRes = await pipefyFetch(mutAnexo, token);
  if (!anexoRes.data?.updateCardField?.success) throw new Error("Falha ao anexar PDF no card");
}

// ─── Helpers ───────────────────────────────────────────────────────────────
async function pipefyFetch(query, token) {
  const res = await fetch(PIPEFY_API, {
    method: "POST",
    headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({ query }),
  });
  const data = await res.json();
  if (data.errors) throw new Error(JSON.stringify(data.errors));
  return data;
}

function parseData(dataStr) {
  if (!dataStr) return null;
  let d;
  if (/^\d{4}-\d{2}-\d{2}$/.test(dataStr)) {
    d = new Date(dataStr + "T12:00:00");
  } else if (/^\d{2}\/\d{2}\/\d{4}$/.test(dataStr)) {
    const [dia, mes, ano] = dataStr.split("/");
    d = new Date(`${ano}-${mes}-${dia}T12:00:00`);
  } else {
    d = new Date(dataStr);
  }
  return isNaN(d.getTime()) ? null : d;
}

function formatarDataPortugues(dataStr) {
  const meses = ["Janeiro","Fevereiro","Marco","Abril","Maio","Junho",
                 "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
  const d = parseData(dataStr);
  if (!d) return dataStr || "";
  return `${d.getDate()} de ${meses[d.getMonth()]} de ${d.getFullYear()}`;
}

function formatarDataDDMMYYYY(dataStr) {
  if (!dataStr) return "";
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(dataStr)) return dataStr;
  const d = parseData(dataStr);
  if (!d) return dataStr;
  return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}/${d.getFullYear()}`;
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
  });
}

function cors() {
  return new Response(null, {
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, X-Worker-Secret",
    },
  });
}
